import unittest
from core import check_winner

class TestCheckWinner(unittest.TestCase):
    def test_row_win_x(self):
        board = [
            ['X', 'O', 'X'],
            ['X', 'O', 'X'],
            ['X', '.', '.']
        ]
        self.assertEqual(check_winner(board), 'X')

    def test_col_win_o(self):
        board = [
            ['X', 'O', 'X'],
            ['.', 'O', '.'],
            ['.', 'O', '.']
        ]
        self.assertEqual(check_winner(board), 'O')

    def test_diag_win_x(self):
        board = [
            ['X', 'O', 'O'],
            ['O', 'X', 'O'],
            ['.', '.', 'X']
        ]
        self.assertEqual(check_winner(board), 'X')

    def test_draw(self):
        board = [
            ['X', 'O', 'X'],
            ['O', 'X', 'O'],
            ['X', 'O', 'X']
        ]
        self.assertEqual(check_winner(board), None)

    def test_no_winner(self):
        board = [
            ['X', '.', 'O'],
            ['.', 'X', '.'],
            ['O', '.', 'X']
        ]
        self.assertIsNone(check_winner(board))

if __name__ == '__main__':
    unittest.main()

